 39	func CreateKafkaProducer(brokers []string, logger *slog.Logger) (sarama.AsyncProducer, error) {
 40		// Set the logger for sarama to use.
 41		sarama.Logger = &saramaLogger{logger: logger}
 42	
 43		saramaConfig := sarama.NewConfig()
 44		saramaConfig.Producer.Return.Successes = true
 45		saramaConfig.Producer.Return.Errors = true
 46	
 47		// Sarama has an issue in a single broker kafka if the kafka broker is restarted.
 48		// This setting is to prevent that issue from manifesting itself, but may swallow failed messages.
 49		saramaConfig.Producer.RequiredAcks = sarama.NoResponse
 50	
 51		saramaConfig.Version = ProtocolVersion
 52	
 53		// So we can know the partition and offset of messages.
 54		saramaConfig.Producer.Return.Successes = true
 55	
 56		producer, err := sarama.NewAsyncProducer(brokers, saramaConfig)
 57		if err != nil {
 58			return nil, err
 59		}
 60	
 61		// We will log to STDOUT if we're not able to produce messages.
 62		go func() {
 63			for err := range producer.Errors() {
 64				logger.Error(fmt.Sprintf("Failed to write message: %+v", err))
 65	
 66			}
 67		}()
 68		return producer, nil
 69	}

