    13	var (
    14		Topic           = getTopic()
    15		ProtocolVersion = sarama.V3_0_0_0
    16	)
    17	
    18	func getTopic() string {
    19		if topic := os.Getenv("KAFKA_TOPIC"); topic != "" {
    20			return topic
    21		}
