 13	
 14	// Prefix checkout's Go service always uses for chargeCard failures (src/checkout/main.go),
 15	// the only signal available to tell a payment decline apart from an unrelated internal error.
 16	const PAYMENT_FAILURE_PREFIX = 'failed to charge card:';
 17	
 18	type TResponse = IProductCheckout | Empty | { error: string; code?: string };
 19	
 20	const handler = async ({ method, body, query }: NextApiRequest, res: NextApiResponse<TResponse>) => {
 21	  switch (method) {
 22	    case 'POST': {
 23	      const { currencyCode = '' } = query;
 24	      const orderData = body as PlaceOrderRequest;
 25	
 26	      let placeOrderResponse: PlaceOrderResponse;
 27	      try {
 28	        placeOrderResponse = await CheckoutGateway.placeOrder(orderData);
 29	      } catch (error) {
 30	        const span = trace.getSpan(context.active());
 31	        span?.recordException(error as Exception);
 32	        span?.setStatus({ code: SpanStatusCode.ERROR });
 33	
 34	        const details = (error as ServiceError)?.details || (error as Error)?.message || '';
 35	
 36	        if (details.startsWith(PAYMENT_FAILURE_PREFIX)) {
 37	          if (!details.includes('code = Unavailable') && !details.includes('code = Internal')) {
 38	            logger.info({ details }, 'Checkout payment declined');
 39	            return res.status(422).json({
 40	              error: 'Your payment could not be processed. Please check your card details and try again.',
 41	              code: 'PAYMENT_FAILED',
 42	            });
 43	          }
 44	        }
 45	
 46	        logger.error({ err: error }, 'Checkout failed to place order');
 47	        return res.status(500).json({ error: 'Failed to place order.' });
 48	      }
 49	
 50	      const { order: { items = [], ...order } = {} } = placeOrderResponse;
 51	
 52	      const productList: IProductCheckoutItem[] = await Promise.all(
 53	        items.map(async ({ item: { productId = '', quantity = 0 } = {}, cost }) => {
 54	          const product = await ProductCatalogService.getProduct(productId, currencyCode as string);
 55	
 56	          return {
 57	            cost,
 58	            item: {
 59	              productId,
 60	              quantity,
 61	              product,
 62	            },
 63	          };
 64	        })
 65	      );
 66	
 67	      logger.info({ 'demo.order.id': placeOrderResponse.order?.orderId }, 'Order placed successfully');
 68	      return res.status(200).json({ ...order, items: productList });
 69	    }
 70	
 71	    default: {
 72	      return res.status(405).send('');
 73	    }
 74	  }
 75	};
 76	
 77	export default InstrumentationMiddleware(handler);
