    34	  const { selectedCurrency } = useCurrency();
    35	  const queryClient = useQueryClient();
    36	  const mutationOptions = useMemo(
    37	    () => ({
    38	      onSuccess: () => {
    39	        queryClient.invalidateQueries({ queryKey: ['cart'] });
    40	      },
    41	    }),
    42	    [queryClient]
    43	  );
