 11	
 12	namespace Accounting;
 13	
 14	internal class DBContext : DbContext
 15	{
 16	    public DbSet<OrderEntity> Orders { get; set; }
 17	    public DbSet<OrderItemEntity> CartItems { get; set; }
 18	    public DbSet<ShippingEntity> Shipping { get; set; }
 19	
 20	    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
 21	    {
 22	        var connectionString = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING");
 23	
 24	        optionsBuilder.UseNpgsql(connectionString).UseSnakeCaseNamingConvention();
 25	    }
 26	}
 27	
 28	
 29	internal class Consumer : BackgroundService
 30	{
 31	    private static readonly string TopicName = Environment.GetEnvironmentVariable("KAFKA_TOPIC") ?? "orders";
 32	
 33	    private readonly ILogger _logger;
 34	    private readonly IConsumer<string, byte[]> _consumer;
 35	    private readonly string? _dbConnectionString;
 36	    private static readonly ActivitySource MyActivitySource = new("Accounting.Consumer");
 37	
 38	    public Consumer(ILogger<Consumer> logger)
 39	    {
 40	        _logger = logger;
 41	
 42	        var servers = Environment.GetEnvironmentVariable("KAFKA_ADDR")
 43	            ?? throw new InvalidOperationException("The KAFKA_ADDR environment variable is not set.");
 44	
 45	        _consumer = BuildConsumer(servers);
 46	        _consumer.Subscribe(TopicName);
 47	
 48	        Log.KafkaConnecting(_logger, servers);
 49	
 50	        _dbConnectionString = Environment.GetEnvironmentVariable("DB_CONNECTION_STRING");
 51	    }
 52	
 53	    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
 54	    {
 55	        await Task.Yield();
 56	
 57	        try
 58	        {
 59	            while (!stoppingToken.IsCancellationRequested)
 60	            {
 61	                try
 62	                {
 63	                    using var activity = MyActivitySource.StartActivity("order-consumed",  ActivityKind.Internal);
 64	                    var consumeResult = _consumer.Consume(stoppingToken);
 65	                    ProcessMessage(consumeResult.Message);
 66	                }
 67	                catch (ConsumeException e)
 68	                {
 69	                    Log.ConsumeError(_logger, e, e.Error.Reason);
 70	                }
 71	            }
 72	        }
 73	        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
 74	        {
 75	        }
 76	        finally
 77	        {
 78	            Log.ConsumerClosing(_logger);
 79	            _consumer.Close();
 80	        }
 81	    }
 82	
 83	    private void ProcessMessage(Message<string, byte[]> message)
 84	    {
 85	        try
 86	        {
 87	            var order = OrderResult.Parser.ParseFrom(message.Value);
 88	            Log.OrderReceivedMessage(_logger, order);
 89	
 90	            if (_dbConnectionString == null)
 91	            {
 92	                return;
 93	            }
 94	
 95	            using var dbContext = new DBContext();
 96	            var orderEntity = new OrderEntity
 97	            {
 98	                Id = order.OrderId
 99	            };
100	            dbContext.Add(orderEntity);
101	            foreach (var item in order.Items)
102	            {
103	                var orderItem = new OrderItemEntity
104	                {
105	                    ItemCostCurrencyCode = item.Cost.CurrencyCode,
106	                    ItemCostUnits = item.Cost.Units,
107	                    ItemCostNanos = item.Cost.Nanos,
108	                    ProductId = item.Item.ProductId,
109	                    Quantity = item.Item.Quantity,
110	                    OrderId = order.OrderId
111	                };
112	
113	                dbContext.Add(orderItem);
114	            }
115	
116	            var shipping = new ShippingEntity
117	            {
118	                ShippingTrackingId = order.ShippingTrackingId,
119	                ShippingCostCurrencyCode = order.ShippingCost.CurrencyCode,
120	                ShippingCostUnits = order.ShippingCost.Units,
121	                ShippingCostNanos = order.ShippingCost.Nanos,
122	                StreetAddress = order.ShippingAddress.StreetAddress,
123	                City = order.ShippingAddress.City,
124	                State = order.ShippingAddress.State,
125	                Country = order.ShippingAddress.Country,
126	                ZipCode = order.ShippingAddress.ZipCode,
127	                OrderId = order.OrderId
128	            };
129	            dbContext.Add(shipping);
130	            dbContext.SaveChanges();
131	        }
132	        catch (DbUpdateException ex) when (ex.InnerException is PostgresException { SqlState: PostgresErrorCodes.UniqueViolation })
133	        {
134	            Log.DuplicateOrderSkipped(_logger);
135	        }
136	        catch (Exception ex)
137	        {
138	            Log.OrderParsingFailed(_logger, ex);
139	        }
140	    }
141	
142	    private static IConsumer<string, byte[]> BuildConsumer(string servers)
143	    {
144	        var conf = new ConsumerConfig
145	        {
146	            GroupId = "accounting",
147	            BootstrapServers = servers,
148	            // https://github.com/confluentinc/confluent-kafka-dotnet/tree/07de95ed647af80a0db39ce6a8891a630423b952#basic-consumer-example
149	            AutoOffsetReset = AutoOffsetReset.Earliest,
150	            EnableAutoCommit = true
151	        };
152	
153	        return new ConsumerBuilder<string, byte[]>(conf)
154	            .Build();
155	    }
156	
157	    public override void Dispose()
158	    {
159	        _consumer?.Dispose();
160	        base.Dispose();
161	    }
162	}

